-- Passage rg3-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b51b3bc0-42c2-5985-b621-f0648f8f9fc4', 'rg3-theme-summary-p02', (select id from public.skills where slug = 'read-g3-theme-summary'), null,
        '3-5', $q$The Harmonica Song$q$, $q$For Kai's birthday, Grandpa Lou mailed a shiny silver harmonica. A note in the box said, "Play me a song when I visit on Sunday."

Kai picked "Twinkle, Twinkle, Little Star" and took a big breath. On the first try, Kai blew as hard as possible. The harmonica let out a loud screech, and the dog ran under the couch.

On the second try, Kai pressed the harmonica against both lips and blew into lots of holes at once. Five notes came out together. It sounded like a goose with a cold.

Kai flopped onto the rug. "I want to put it back in the box forever."

Kai's older sister, Rosa, sat down on the rug. "What did each try teach you?" Rosa asked.

Kai thought about it. "Blowing hard makes a screech. And too many holes make a mess."

"Then each mistake showed you something to fix," Rosa said.

So Kai practiced every afternoon. Kai blew soft, slow breaths. Kai made a small circle with both lips so only one hole sounded at a time. On a card, Kai wrote down which hole made each note.

On Sunday, Kai played the whole song for Grandpa Lou. A few notes still wobbled, but the tune was clear. Grandpa clapped and clapped. "Every wobble is a step forward," Grandpa said. "That is how I learned, too."$q$, 'draft')
