  ('f9b40ea8-a5d3-5224-8102-a18381521429', null, (select id from public.skills where slug = 'read-g3-theme-summary'), null, 'medium',
   $q$How do Grandma's words help teach the lesson of the poem?$q$, $q$[{"text":"Grandma shows the speaker how to plant a seed in a cup.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Grandma says that the seed is to blame for not growing.","is_correct":false,"misconception_token":"misattributes-line"},{"text":"Grandma digs out the seed to see what is wrong with it.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Grandma tells the speaker to wait, and waiting is what lets the bean sprout.","is_correct":true}]$q$::jsonb, $q$Grandma tells the speaker to wait, and waiting is what lets the bean sprout.$q$, $q$Grandma says, "Wait. It will sprout," and the speaker listens and is rewarded on Saturday. The question "Was the seed to blame?" is the speaker's, not Grandma's.$q$, 'draft', '0f4c9a89-f31b-5844-b0a7-bef9623cf1ce')
