-- Passage rg3-theme-summary-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7b31b983-d958-5e59-99f3-f5eeb4f6a8ef', 'rg3-theme-summary-p07', (select id from public.skills where slug = 'read-g3-theme-summary'), null,
        '3-5', $q$The Parrot Who Talked and the Owl Who Listened$q$, $q$In a thick green jungle, a parrot and an owl lived in the same tall tree. Parrot loved to talk. From morning until night, Parrot chattered about its bright feathers, its loud voice, and how much it knew.

Owl did not say much. Owl sat on a branch, blinked its round eyes, and listened.

One evening, a young monkey came to the tree, crying. "I followed a butterfly too far, and now I cannot find my family," Monkey said.

"I know this jungle better than anyone!" Parrot squawked. "Go left at the big rock. No, go right at the river. Or maybe it was the hill." Parrot kept talking, and Monkey grew more and more confused.

Owl flew down to a low branch. "Tell me what you saw before you got lost," Owl said softly.

Monkey thought. "I saw a waterfall. And I heard drums from the frogs in the pond."

Owl tilted its head and listened. Far away, there was a soft drumming sound. "The frog pond is that way," Owl said, pointing with one wing. "Your family must be near it."

Monkey hurried off and soon found its family by the pond.

The next morning, Parrot was quiet for a long time. Then it said, "Owl, how did you know the way?"

"I did not know," said Owl. "I only listened."$q$, 'draft')
