-- Passage rg3-word-parts-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('5361b4de-9bb4-58ac-a35a-b0be929b565d', 'rg3-word-parts-p06', (select id from public.skills where slug = 'read-g3-word-parts'), null,
        '3-5', $q$A Second Life for Old Things$q$, $q$Every week, families throw away bags of trash. Much of it ends up in a landfill, a huge pile of garbage covered with dirt. But many things we throw out are not really useless. They can have a second life.

One way to help is to reuse things. A glass jar can hold pencils. An old shirt can become a cleaning rag. Reusing means using something again instead of buying something new.

Another way is to recycle. Paper, cans and some plastics can be melted or mashed and made into new things. Many towns give families special bins. Workers sort the items so each kind goes to the right place.

Some unwanted things can be given away. A jacket that is too small for one child may fit another child perfectly. Toys, books and games can be given to a school or a shelter.

Small changes make a big difference. When people reuse, recycle and give, they keep trash out of landfills. That makes the planet a cleaner place for everyone.$q$, 'draft')
