insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f5af89f5-7982-5da6-a9e6-96952857d88b', 'rg4-context-clues-p04', (select id from public.skills where slug = 'read-g4-context-clues'), null,
        '3-5', $q$The Blanket Box$q$, $q$Amara and her friend Tomas wanted to help the animal shelter on Birch Street. The shelter was running out of blankets for its dogs and cats. The animals needed something soft and warm to sleep on, especially in winter.

"Let's hold a blanket drive," Amara said. "We can collect blankets from the whole neighborhood." Tomas nodded. "We can ask people to donate old blankets, giving them to the shelter for free."

The two friends made bright posters and hung them at the library and the corner store. At first, only three blankets came in. Amara felt discouraged. She began to wonder if anyone had even read the posters, and she almost wanted to give up.

Then Mrs. Lindqvist from next door had an idea. "Put a big box on your porch," she said. "People will see it every day when they walk by." The plan worked. Soon the box was overflowing, with blankets spilling over the sides and piling up on the steps.

On Saturday, Amara and Tomas brought six bags of blankets to the shelter. The shelter worker, Mr. Oduya, was grateful. He shook their hands and thanked them again and again. That night, every dog and cat had a cozy bed.$q$, 'draft')
